CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "issue_comments_agent_client_request_uq" ON "issue_comments" USING btree ("company_id","issue_id","author_agent_id","client_request_id") WHERE "issue_comments"."author_agent_id" IS NOT NULL AND "issue_comments"."client_request_id" IS NOT NULL;